const settings = $('Load Action Settings').first()?.json ?? {};
const request = $('Email Template Editor Actions Webhook').first()?.json ?? $input.first()?.json ?? {};
const body = request.body ?? request.query ?? request;
const headers = request.headers ?? {};
const clean = (value) => value === null || value === undefined ? '' : String(value).trim();
const parseId = (value) => {
  const n = Number.parseInt(clean(value), 10);
  return Number.isInteger(n) && n > 0 ? n : null;
};
const parseType = (value) => {
  const n = Number.parseInt(clean(value), 10);
  return Number.isInteger(n) && [0, 1, 2].includes(n) ? n : 0;
};
const parseBool = (value) => ['1', 'true', 'yes', 'y', 'on'].includes(clean(value).toLowerCase());
const hasLiteralUndefined = (value) => /\bundefined\b/i.test(String(value ?? ''));
const deriveBaseUrl = (sourceHeaders, fallback) => {
  const forwardedProto = clean(sourceHeaders['x-forwarded-proto']);
  const forwardedHost = clean(sourceHeaders['x-forwarded-host']);
  const host = forwardedHost || clean(sourceHeaders.host);
  const forwardedPort = clean(sourceHeaders['x-forwarded-port']);
  if (!host) return fallback;
  const proto = forwardedProto || 'http';
  let authority = host;
  if (forwardedPort && !authority.includes(':')) {
    const isDefault = (proto === 'http' && forwardedPort === '80') || (proto === 'https' && forwardedPort === '443');
    if (!isDefault) authority += ':' + forwardedPort;
  }
  return proto + '://' + authority;
};
const decodeBase64 = (value) => {
  const raw = clean(value).replace(/\s+/g, '');
  if (!raw) return null;
  try {
    return Buffer.from(raw, 'base64');
  } catch {
    return null;
  }
};
const decodeUtf8Field = (primary, fallback = '') => {
  const buffer = decodeBase64(primary);
  return buffer ? buffer.toString('utf8') : fallback;
};
const stripDataUrlPrefix = (value) => {
  const raw = String(value ?? '').trim();
  const match = raw.match(/^data:([^;,]+);base64,(.+)$/i);
  return match ? { contentType: clean(match[1]).toLowerCase(), base64: clean(match[2]) } : { contentType: '', base64: clean(raw) };
};
const normalizeImageKey = (value) => clean(value)
  .toLowerCase()
  .replace(/\.[a-z0-9]{1,8}$/i, '')
  .replace(/[^a-z0-9]+/g, '_')
  .replace(/^_+|_+$/g, '')
  .slice(0, 120);
const inferContentType = (fileName, provided) => {
  const normalizedProvided = clean(provided).toLowerCase();
  if (normalizedProvided) return normalizedProvided;
  const lowerFileName = clean(fileName).toLowerCase();
  if (lowerFileName.endsWith('.png')) return 'image/png';
  if (lowerFileName.endsWith('.jpg') || lowerFileName.endsWith('.jpeg')) return 'image/jpeg';
  if (lowerFileName.endsWith('.gif')) return 'image/gif';
  if (lowerFileName.endsWith('.webp')) return 'image/webp';
  return '';
};
const inferFileExt = (fileName, contentType) => {
  const lowerFileName = clean(fileName).toLowerCase();
  const fileNameMatch = lowerFileName.match(/\.([a-z0-9]{1,8})$/i);
  if (fileNameMatch) return fileNameMatch[1];
  return ({ 'image/png': 'png', 'image/jpeg': 'jpg', 'image/gif': 'gif', 'image/webp': 'webp' })[clean(contentType).toLowerCase()] || 'bin';
};
const fallbackBaseUrl = clean(settings.n8n_base_url) || 'http://n8n:5678';
const n8nBaseUrl = deriveBaseUrl(headers, fallbackBaseUrl);
const action = clean(body.action);
const templateId = parseId(body.template_id);
const returnUrl = clean(body.return_url) || (n8nBaseUrl + '/webhook/email-template-editor');
const decodedSubject = clean(decodeUtf8Field(body.subject_template_b64, body.subject_template));
const decodedText = decodeUtf8Field(body.text_template_b64, body.text_template ?? '');
const decodedHtml = decodeUtf8Field(body.html_template_b64, body.html_template ?? '');
const imageSource = stripDataUrlPrefix(body.image_base64);
const imageBuffer = imageSource.base64 ? decodeBase64(imageSource.base64) : null;
const fileName = clean(body.file_name) || clean(body.image_key) || 'image';
const contentType = inferContentType(fileName, clean(body.content_type) || imageSource.contentType);
const imageKey = normalizeImageKey(clean(body.image_key) || fileName);
const payload = {
  action,
  template_id: templateId,
  template_key: clean(body.template_key),
  template_name: clean(body.template_name),
  template_type: parseType(body.template_type),
  subject_template: clean(body.subject_template),
  text_template: body.text_template ?? '',
  html_template: body.html_template ?? '',
  subject_template_b64: clean(body.subject_template_b64),
  text_template_b64: clean(body.text_template_b64),
  html_template_b64: clean(body.html_template_b64),
  is_active: parseBool(body.is_active),
  return_url: returnUrl,
  n8n_base_url: n8nBaseUrl,
  image_key: imageKey,
  file_name: fileName,
  file_ext: inferFileExt(fileName, contentType),
  content_type: contentType,
  image_base64: imageBuffer ? imageBuffer.toString('base64') : imageSource.base64,
  byte_size: imageBuffer ? imageBuffer.length : 0,
  source_path: clean(body.source_path) || 'uploaded:email-template-editor',
  error_message: '',
};
const imageActions = new Set(['upsert_image', 'activate_image', 'deactivate_image']);
if (action === 'create_template') {
  if (!payload.template_key) payload.error_message = 'Template key is required.';
  else if (!payload.template_name) payload.error_message = 'Template name is required.';
} else if (action === 'update_template') {
  if (!payload.template_id) payload.error_message = 'A valid template is required.';
  else if (!payload.template_key) payload.error_message = 'Template key is required.';
  else if (!payload.template_name) payload.error_message = 'Template name is required.';
} else if (action === 'delete_template') {
  if (!payload.template_id) payload.error_message = 'A valid template is required.';
} else if (action === 'upsert_image') {
  if (!payload.image_key) payload.error_message = 'Image key is required.';
  else if (!payload.file_name) payload.error_message = 'Image file name is required.';
  else if (!payload.content_type) payload.error_message = 'Image content type is required.';
  else if (!['image/png', 'image/jpeg', 'image/gif', 'image/webp'].includes(payload.content_type)) payload.error_message = 'Only PNG, JPEG, GIF, and WebP images are supported.';
  else if (!imageBuffer || payload.byte_size <= 0) payload.error_message = 'Image data is required.';
} else if (imageActions.has(action)) {
  if (!payload.image_key) payload.error_message = 'Image key is required.';
} else {
  payload.error_message = 'Unsupported action.';
}
if (!payload.error_message && !imageActions.has(action) && action !== 'delete_template' && [decodedSubject, decodedText, decodedHtml].some(hasLiteralUndefined)) {
  payload.error_message = 'Template content contains literal "undefined". Restore the template variable placeholder before saving.';
}
return [{ json: payload }];

const input = $input.first().json ?? {};
const sqlLiteral = (value) => value === null || value === undefined ? 'NULL' : "'" + String(value).replace(/'/g, "''") + "'";
const sqlBase64Utf8 = (value) => {
  const raw = value === null || value === undefined ? '' : String(value).trim();
  return raw ? "convert_from(decode('" + raw.replace(/'/g, "''") + "','base64'),'UTF8')" : null;
};
const sqlByteaBase64 = (value) => {
  const raw = value === null || value === undefined ? '' : String(value).trim();
  return raw ? "decode('" + raw.replace(/'/g, "''") + "','base64')" : 'NULL';
};
const subjectExpr = sqlBase64Utf8(input.subject_template_b64) || sqlLiteral(input.subject_template);
const textExpr = sqlBase64Utf8(input.text_template_b64) || sqlLiteral(input.text_template);
const htmlExpr = sqlBase64Utf8(input.html_template_b64) || sqlLiteral(input.html_template);
let sql = '';
let successTitle = 'Saved';
let successMessage = 'Template saved.';
if (input.action === 'create_template') {
  sql = [
    'INSERT INTO public.email_templates (template_key, template_name, template_type, subject_template, text_template, html_template, is_active, created_at, updated_at)',
    'VALUES (' + [sqlLiteral(input.template_key), sqlLiteral(input.template_name), String(input.template_type || 0), subjectExpr, textExpr, htmlExpr, input.is_active ? 'TRUE' : 'FALSE', 'now()', 'now()'].join(', ') + ')',
    'RETURNING id::text AS template_id'
  ].join('\n');
  successTitle = 'Template created';
  successMessage = 'Template created.';
} else if (input.action === 'update_template') {
  sql = [
    'UPDATE public.email_templates',
    'SET template_key = ' + sqlLiteral(input.template_key) + ',',
    '    template_name = ' + sqlLiteral(input.template_name) + ',',
    '    template_type = ' + String(input.template_type || 0) + ',',
    '    subject_template = ' + subjectExpr + ',',
    '    text_template = ' + textExpr + ',',
    '    html_template = ' + htmlExpr + ',',
    '    is_active = ' + (input.is_active ? 'TRUE' : 'FALSE') + ',',
    '    updated_at = now()',
    'WHERE id = ' + String(input.template_id),
    'RETURNING id::text AS template_id'
  ].join('\n');
  successTitle = 'Template updated';
  successMessage = 'Template updated.';
} else if (input.action === 'delete_template') {
  sql = [
    'WITH deleted AS (',
    '  DELETE FROM public.email_templates WHERE id = ' + String(input.template_id) + ' RETURNING id',
    ')',
    'SELECT COALESCE(MAX(id),0)::text AS template_id FROM deleted'
  ].join('\n');
  successTitle = 'Template deleted';
  successMessage = 'Template deleted.';
} else if (input.action === 'upsert_image') {
  sql = [
    'WITH upserted AS (',
    '  INSERT INTO public.images (image_key, file_name, file_ext, content_type, byte_size, source_path, data, is_active, created_at, updated_at)',
    '  VALUES (' + [sqlLiteral(input.image_key), sqlLiteral(input.file_name), sqlLiteral(input.file_ext), sqlLiteral(input.content_type), String(Number.parseInt(input.byte_size, 10) || 0), sqlLiteral(input.source_path), sqlByteaBase64(input.image_base64), 'TRUE', 'now()', 'now()'].join(', ') + ')',
    '  ON CONFLICT (image_key) DO UPDATE',
    '  SET file_name = EXCLUDED.file_name,',
    '      file_ext = EXCLUDED.file_ext,',
    '      content_type = EXCLUDED.content_type,',
    '      byte_size = EXCLUDED.byte_size,',
    '      source_path = EXCLUDED.source_path,',
    '      data = EXCLUDED.data,',
    '      is_active = TRUE,',
    '      updated_at = now()',
    '  RETURNING image_key',
    ')',
    'SELECT image_key FROM upserted LIMIT 1'
  ].join('\n');
  successTitle = 'Image uploaded';
  successMessage = 'Managed image saved.';
} else if (input.action === 'activate_image' || input.action === 'deactivate_image') {
  const nextState = input.action === 'activate_image' ? 'TRUE' : 'FALSE';
  sql = [
    'UPDATE public.images',
    'SET is_active = ' + nextState + ',',
    '    updated_at = now()',
    'WHERE image_key = ' + sqlLiteral(input.image_key),
    'RETURNING image_key'
  ].join('\n');
  successTitle = input.action === 'activate_image' ? 'Image reactivated' : 'Image deactivated';
  successMessage = input.action === 'activate_image' ? 'Managed image reactivated.' : 'Managed image deactivated.';
}
return [{ json: { ...input, sql, success_title: successTitle, success_message: successMessage } }];

const input = $('Build Action SQL').first()?.json ?? {};
const result = $input.first()?.json ?? {};
const clean = (value) => value === null || value === undefined ? '' : String(value).trim();
const baseReturnPath = (input.return_url || '').split('?')[0] || '';
let redirectTo = input.return_url || (input.n8n_base_url + '/webhook/email-template-editor');
if (input.action === 'delete_template') {
  redirectTo = baseReturnPath || input.n8n_base_url + '/webhook/email-template-editor';
} else if (input.action === 'create_template' || input.action === 'update_template') {
  const templateId = clean(result.template_id) || clean(input.template_id);
  redirectTo = (baseReturnPath || input.n8n_base_url + '/webhook/email-template-editor') + (templateId ? ('?template_id=' + encodeURIComponent(templateId)) : '');
}
redirectTo += (redirectTo.includes('?') ? '&' : '?') + 'message=' + encodeURIComponent(input.success_message || 'Saved');
const escapeHtml = (value) => String(value ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&#39;');
const html = '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta http-equiv="refresh" content="0; url=' + escapeHtml(redirectTo) + '"><meta name="viewport" content="width=device-width, initial-scale=1"><title>' + escapeHtml(input.success_title || 'Saved') + '</title></head><body><p>Saved. Redirecting…</p><p><a href="' + escapeHtml(redirectTo) + '">Continue</a></p></body></html>';
return [{ json: { html } }];
